(function execute(inputs, outputs) {
	var pwdUtil = new global.ExternalUserRegistrationUtil();
	// var result = this.newItem("result");
	pwdUtil.sendResetEmail(inputs.user, inputs.password_reset_request, {}, inputs.profile);
})(inputs, outputs);

